do $$
declare k text;
begin
  select decrypted_secret into k from vault.decrypted_secrets where name = 'biomarker_lock_key' limit 1;
  if k is null or k = '' then raise exception 'Biomarker unlock key unavailable; aborting'; end if;
  perform set_config('app.biomarker_unlock', k, true);
end $$;

update public.biomarker_hub set name = 'Yeast (Microscopy)', synonyms = case when 'Yeast' = any(coalesce(synonyms,'{}'::text[])) then synonyms else coalesce(synonyms,'{}'::text[]) || 'Yeast'::text end, last_updated = now()
 where name = 'Yeast' and status = 'active' and not exists (select 1 from public.biomarker_hub where lower(name) = 'yeast (microscopy)');

update public.provider_test_biomarkers b set biomarker_id = h.id, match_method = 'exact_synonym'
  from public.provider_tests t, public.biomarker_hub h
 where b.provider_test_id = t.id and t.test_name ilike '%allerg%' and b.raw_label = 'Yeast'
   and h.name = 'Baker''s yeast' and h.status = 'active' and b.biomarker_id is distinct from h.id;

select bioaudit.fill($j$[{"n":"Cross-reactive carbohydrate determinants","w":"The level of IgE antibodies to cross-reactive carbohydrate determinants (CCDs), sugar side chains found on many plant, pollen and insect venom proteins.","u":"kUA/L","hi":"CCD sensitisation, which can cause false-positive allergy test results","lo":"-","gl":"No antibodies to CCDs were detected, so CCD cross-reactivity is unlikely to explain other positive results.","gh":"Antibodies to CCDs are present. Other positive allergy tests may reflect CCD cross-reactivity rather than true allergy.","ug":"Call 999 if you have swelling of the face or throat, difficulty breathing or feel faint after exposure to a suspected allergen.","im":"No treatment is needed for CCD sensitisation itself. Your clinician may use component tests to check which results matter.","rr":{"both":{"normal":["< 0.35","Negative (class 0)","No CCD antibodies detected."],"high":["≥ 0.35","Positive","CCD antibodies detected. Other positive allergy results may be due to cross-reactivity."]}},"c":["Pollen allergy","Venom allergy","False-positive allergy tests"],"f":["No lifestyle changes are needed for CCD sensitisation itself"],"z":["Total IgE","Specific IgE"]}]$j$::jsonb);

